package io.github.diodeme.ji.remote;

import java.nio.file.Path;
import java.util.Optional;
import java.util.OptionalInt;

/**
 * Structured SSH target. A missing user or port means "delegate to the user's own SSH configuration":
 * the host is passed through unchanged and no {@code -p} is emitted.
 */
public record SshTarget(String host, Optional<String> user, OptionalInt port, Optional<Path> identityFile) {
    public SshTarget {
        if (host == null || host.isBlank()) throw new IllegalArgumentException("invalid SSH host");
        if (host.startsWith("-") || host.chars().anyMatch(Character::isWhitespace)) {
            throw new IllegalArgumentException("unsafe SSH host");
        }
        user = user == null ? Optional.empty() : user.filter(value -> !value.isBlank());
        if (user.isPresent() && !user.orElseThrow().matches("[A-Za-z0-9._-]+")) {
            throw new IllegalArgumentException("unsafe SSH user");
        }
        port = port == null ? OptionalInt.empty() : port;
        port.ifPresent(value -> { if (value < 1 || value > 65_535) throw new IllegalArgumentException("invalid SSH port"); });
        identityFile = identityFile == null ? Optional.empty() : identityFile;
    }

    public String destination() {
        return user.map(value -> value + "@").orElse("") + host;
    }
}
```

