```java
package io.github.diodeme.ji.remote;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * Single authority for SSH/SCP argv assembly. Arguments stay structured: the target is never handed to a
 * shell, and an identity file is referenced by path only.
 *
 * <p>A bound known hosts file switches the connection to {@code StrictHostKeyChecking=yes} and keeps host key
 * trust inside the caller's own file. Without one the connection keeps OpenSSH's default trust configuration.
 */
public final class SshCommandLine {
    private final Optional<Path> knownHostsFile;

    public SshCommandLine(Optional<Path> knownHostsFile) {
        this.knownHostsFile = knownHostsFile == null ? Optional.empty()
                : knownHostsFile.map(path -> path.toAbsolutePath().normalize());
    }

    /** ssh argv with no remote command; callers append the destination and the command. */
    public List<String> ssh(SshTarget target) {
        var command = new ArrayList<String>();
        command.add("ssh");
        command.addAll(connectionArguments(target, "-p"));
        return List.copyOf(command);
    }

    public List<String> scp(SshTarget target, Path source, String destination) {
        var command = new ArrayList<String>();
        command.add("scp");
        command.addAll(connectionArguments(target, "-P"));
        command.add(source.toAbsolutePath().normalize().toString());
        command.add(target.destination() + ":" + destination);
        return List.copyOf(command);
    }

    private List<String> connectionArguments(SshTarget target, String portOption) {
        var arguments = new ArrayList<String>();
        target.port().ifPresent(port -> arguments.addAll(List.of(portOption, Integer.toString(port))));
        arguments.addAll(List.of("-o", "BatchMode=yes"));
        knownHostsFile.ifPresent(file -> arguments.addAll(List.of(
                "-o", "UserKnownHostsFile=" + file, "-o", "StrictHostKeyChecking=yes")));
        target.identityFile().ifPresent(path -> arguments.addAll(List.of(
                "-i", path.toAbsolutePath().normalize().toString())));
        return arguments;
    }
}
```

