 */
final class CancellableProcessRunner implements ProcessRunner {
    private final ProcessRunner delegate;
    private final Set<RunningProcess> live = ConcurrentHashMap.newKeySet();
    private volatile boolean cancelled;

    CancellableProcessRunner(ProcessRunner delegate) { this.delegate = delegate; }

