```java
@Override
public Result run(List<String> command, Duration timeout) {
    requireActive();
    var holder = new java.util.concurrent.atomic.AtomicReference<RunningProcess>();
    try {
        return delegate.run(command, timeout, process -> { holder.set(process); live.add(process); });
    } finally {
        RunningProcess process = holder.get();
        if (process != null) live.remove(process);
    }
}
```
