@Override public RunningProcess start(List<String> command) {
    requireActive();
    RunningProcess process = delegate.start(command);
    live.add(process);
    if (cancelled) { live.remove(process); process.close(); throw new OperationCancelledException(); }
    return new RunningProcess() {
        @Override public boolean isAlive() { return process.isAlive(); }
        @Override public void close() { live.remove(process); process.close(); }
    };
}
```
